package com.vahotel.web;import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.ArrayNode;import com.fasterxml.jackson.databind.node.ObjectNode;import java.net.URI;import java.net.http.*;import java.time.Duration;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;
@Controller public class ChatbotController {@Value("${groq.api.key:}") private String key;@Value("${groq.api.url:https://api.groq.com/openai/v1/chat/completions}") private String url;@Value("${groq.api.model:llama-3.3-70b-versatile}") private String model;private final ObjectMapper mapper=new ObjectMapper();
 @GetMapping("/chatbot") public String page(){return "chatbot";}@PostMapping("/chatbot") public String ask(@RequestParam String question,Model m){String answer;if(key==null||key.isBlank()){answer="The hotel assistant is in basic FAQ mode. Browse rooms, ask management about reservations or cancellations, and never enter real card details in this local development version.";}else{try{ObjectNode body=mapper.createObjectNode();body.put("model",model);ArrayNode msgs=body.putArray("messages");msgs.addObject().put("role","system").put("content","You are VA Hotel's concise guest support assistant. Answer only general hotel questions. Never claim to access private bookings, charge payments, or approve refunds.");msgs.addObject().put("role","user").put("content",question);HttpRequest req=HttpRequest.newBuilder(URI.create(url)).timeout(Duration.ofSeconds(25)).header("Authorization","Bearer "+key).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(mapper.writeValueAsString(body))).build();HttpResponse<String> res=HttpClient.newHttpClient().send(req,HttpResponse.BodyHandlers.ofString());JsonNode json=mapper.readTree(res.body());answer=res.statusCode()==200?json.path("choices").path(0).path("message").path("content").asText("I could not prepare an answer."):"The assistant service is temporarily unavailable.";}catch(Exception e){answer="The assistant service is temporarily unavailable. Please contact hotel staff.";}}m.addAttribute("question",question);m.addAttribute("answer",answer);return "chatbot";}}
